{/* RIGHT IMAGES */}
<div className="relative h-[520px] w-full">

  {/* Main Image */}
  <motion.img
    src={images[0].src}
    alt="Gym Interior"
    className="absolute top-0 left-0 w-full h-64 object-cover rounded-2xl shadow-2xl"
    initial={{ opacity: 0, y: 40 }}
    whileInView={{ opacity: 1, y: 0 }}
    transition={{ duration: 0.8 }}
    viewport={{ once: true }}
  />

  {/* Center Image */}
  <motion.img
    src={images[1].src}
    alt="Equipment"
    className="absolute top-44 left-1/2 -translate-x-1/2 w-64 h-52 object-cover rounded-xl shadow-xl border border-white/10 z-20"
    animate={{ y: [0, -12, 0] }}
    transition={{ duration: 6, repeat: Infinity }}
  />

  {/* Bottom Left */}
  <motion.img
    src={images[2].src}
    alt="Workout Floor"
    className="absolute bottom-0 left-0 w-56 h-44 object-cover rounded-xl shadow-lg border border-white/10"
    animate={{ y: [0, 10, 0] }}
    transition={{ duration: 7, repeat: Infinity }}
  />

  {/* Bottom Right */}
  <motion.img
    src={images[3].src}
    alt="Clean Gym"
    className="absolute bottom-6 right-0 w-48 h-40 object-cover rounded-xl shadow-lg border border-white/10"
    animate={{ y: [0, -8, 0] }}
    transition={{ duration: 5, repeat: Infinity }}
  />

</div>
